const entities = items.map(i => i.json);
const byId = (id) => entities.find(e => e.entity_id === id);

const now = new Date();
const zone = byId('zone.home');
// Dynamically fallback to Africa/Algiers if the zone entity doesn't provide it
const targetTz = zone?.attributes?.time_zone ?? 'Africa/Algiers';

// ─── Helpers ─────────────────────────────────────────────────────────────────

function randomRunId() {
  const hex = () => Math.floor(Math.random() * 0xffffff).toString(16).padStart(6, '0');
  return `${hex()}-${Math.floor(Math.random() * 0xffffffffffff).toString(16).padStart(12, '0')}`;
}

// ✅ NEW: Dynamically calculates the offset string (e.g., "+01:00") based on zone.home
function getDynamicOffsetStr(date) {
  const utc = new Date(date.toLocaleString('en-US', { timeZone: 'UTC' }));
  const loc = new Date(date.toLocaleString('en-US', { timeZone: targetTz }));
  const diffMinutes = Math.round((loc - utc) / 60000);
  const sign = diffMinutes >= 0 ? '+' : '-';
  const pad = (num) => String(Math.floor(Math.abs(num))).padStart(2, '0');
  return `${sign}${pad(diffMinutes / 60)}:${pad(diffMinutes % 60)}`;
}

function toISO(datetimeStr) {
  if (!datetimeStr || datetimeStr === 'unknown') return null;
  // If it's just a date without a time, parse it directly
  if (!datetimeStr.includes(' ')) return new Date(datetimeStr);

  // Appends the dynamic offset calculated from zone.home
  return new Date(datetimeStr.replace(' ', 'T') + getDynamicOffsetStr(now));
}

function formatTime(date) {
  if (!date) return null;
  // Calculate exact millisecond difference for the target timezone
  const utc = new Date(date.toLocaleString('en-US', { timeZone: 'UTC' }));
  const loc = new Date(date.toLocaleString('en-US', { timeZone: targetTz }));
  const diffMinutes = Math.round((loc - utc) / 60000);

  // Apply difference to generate the correct visual ISO string with offset
  const localTime = new Date(date.getTime() + (diffMinutes * 60000));
  return localTime.toISOString().slice(0, 19) + getDynamicOffsetStr(date);
}

function diffMinutes(from, to) {
  if (!from || !to) return null;
  return Math.round((to - from) / 60000);
}

function safeParse(value) {
  if (value === null || value === undefined) return null;
  if (value === 'unknown' || value === 'unavailable') return null;

  const num = parseFloat(value);
  return isNaN(num) ? null : num;
}

// ─── Entity lookups ───────────────────────────────────────────────────────────

const cropType     = byId('input_select.crop_type');
const growthStage  = byId('input_select.growth_stage');
const priorityMode = byId('input_select.priority_mode');

const soilMoisture = byId('sensor.farm_soil_moisture');
const temperature  = byId('sensor.farm_temperature');
const airHumidity  = byId('sensor.farm_humidity');
const luminosity   = byId('sensor.farm_ambient_light');

// ─── Actuator builder ─────────────────────────────────────────────────────────

function buildActuator(type) {
  const controlModeRaw = byId(`input_boolean.${type}_control_mode`)?.state ?? null;
  const status         = type==="pump" ?   byId(`switch.${type}_status`)?.state: byId(`input_boolean.${type}_status`)?.state
    ;

  const executeAtDate    = toISO(byId(`input_datetime.${type}_execute_at`)?.state);
  const executeUntilDate = toISO(byId(`input_datetime.${type}_execute_until`)?.state);
  const reEvalStartDate  = toISO(byId(`input_datetime.${type}_re_evaluation_start`)?.state);
  const reEvalEndDate    = toISO(byId(`input_datetime.${type}_re_evaluation_end`)?.state);

  const executeAtStr    = formatTime(executeAtDate);
  const executeUntilStr = formatTime(executeUntilDate);

  const isValidReEval  = reEvalStartDate && reEvalEndDate && (reEvalStartDate < reEvalEndDate);
  const reEvalExpired  = !isValidReEval || now > reEvalEndDate;
  const isFutureOrActiveReEval = isValidReEval && now <= reEvalEndDate;

  const reEvalStartStr = reEvalExpired ? null : formatTime(reEvalStartDate);
  const reEvalEndStr   = reEvalExpired ? null : formatTime(reEvalEndDate);

  let controlMode;
  if (controlModeRaw !== "on")      controlMode = 'auto';
  else if (controlModeRaw === "on") controlMode = 'semi-auto';
  else                              controlMode = null;

  if (isFutureOrActiveReEval) {
    // Check if the current time has actually reached the start of the re-evaluation range
    const isCurrentlyActive = now >= reEvalStartDate;
    const shouldSkip = !isCurrentlyActive; // Skip is true if it's in the future, false if active

    return {
      type,
      status,
      control_mode: controlMode,
      // ✅ Dynamic classification based on whether we are currently in the range or waiting for it
      classification: isCurrentlyActive ? 'NOW-RE-EVALUATING' : 'FUTURE-RE-EVALUATING',
      skipped: shouldSkip,
      ...(controlModeRaw === "on" ? { recommended_action: null } : {}),
      run: { active: false, execute_at: null, duration_minutes: null, execute_until: null },
      re_evaluation: {
        active: true,
        skipped: shouldSkip,
        interval: { start: reEvalStartStr, end: reEvalEndStr }
      }
    };
  }

  if (controlModeRaw !== "on") {
    const executeUntilExpired = !executeUntilDate || now > executeUntilDate;

    // The base validation logic preserved
    const isValidRun = executeAtDate && executeUntilDate && (executeAtDate < executeUntilDate);

    if (!isValidRun) {
      if (executeUntilExpired) {
        return {
          type, status, control_mode: controlMode,
          classification: 'FREE', skipped: false,
          run: { active: false, execute_at: null, duration_minutes: null, execute_until: null },
          re_evaluation: { active: false, skipped: false, interval: { start: null, end: null } }
        };
      } else {
        const fallbackClass = status === 'on' ? 'WORKING' : 'FREE';
        return {
          type, status, control_mode: controlMode,
          classification: fallbackClass, 
          skipped: fallbackClass === 'WORKING',
          run: { active: false, execute_at: null, duration_minutes: null, execute_until: null },
          re_evaluation: { active: false, skipped: false, interval: { start: null, end: null } }
        };
      }
    }

    if (executeUntilExpired) {
      return {
        type, status, control_mode: controlMode,
        classification: 'FREE', skipped: false,
        run: { active: false, execute_at: null, duration_minutes: null, execute_until: null },
        re_evaluation: { active: false, skipped: false, interval: { start: null, end: null } }
      };
    }

    const duration = diffMinutes(executeAtDate, executeUntilDate);

    if (now < executeAtDate) {
      return {
        type, status, control_mode: controlMode,
        classification: 'PENDING', skipped: true,
        run: {
          active: true, execute_at: executeAtStr, duration_minutes: duration, execute_until: executeUntilStr
        },
        re_evaluation: { active: false, skipped: false, interval: { start: reEvalStartStr, end: reEvalEndStr } }
      };
    } else {
      return {
        type, status, control_mode: controlMode,
        classification: 'WORKING', skipped: true,
        run: {
          active: true, execute_at: executeAtStr, duration_minutes: duration, execute_until: executeUntilStr
        },
        re_evaluation: { active: false, skipped: false, interval: { start: reEvalStartStr, end: reEvalEndStr } }
      };
    }
  }

  // Semi-Auto mode
  if (controlModeRaw === "on") {
    return {
      type, status, control_mode: controlMode,
      classification: status === 'on' ? 'ON' : 'OFF',
      skipped: false, recommended_action: null,
      run: { active: false, execute_at: null, duration_minutes: null, execute_until: null },
      re_evaluation: { active: false, skipped: false, interval: { start: null, end: null } }
    };
  }

  return {
    type, status, control_mode: controlMode,
    classification: null, skipped: false,
    run: { active: false, execute_at: null, duration_minutes: null, execute_until: null },
    re_evaluation: { active: false, skipped: false, interval: { start: null, end: null } }
  };
}

// ─── Warnings ─────────────────────────────────────────────────────────────────

const warningKeys = [
  'frost_risk', 'heavy_rainfall', 'high_humidity_level',
  'high_temperature_detected', 'insufficient_sunlight',
  'excessive_sunlight', 'low_soil_moisture', 'overwatering', 'strong_wind'
];

const warnings = warningKeys.map(key => ({
  name: key,
  active: byId(`input_boolean.${key}`)?.state === 'on',
  severity: null,
  description: null
}));

// ─── Build actuators ──────────────────────────────────────────────────────────

const pumpActuator = buildActuator('pump');
const fanActuator  = buildActuator('fan');

// ─── Assemble output ──────────────────────────────────────────────────────────

const output = {
  meta: {
    run_id: randomRunId(),
    // Now explicitly uses formatTime() so it mathematically matches all other time fields perfectly!
    triggered_at: formatTime(now), 
    adr: $('Code in JavaScript').first().json.piAdr
  },
  location: {
    latitude:  zone?.attributes?.latitude  ?? null,
    longitude: zone?.attributes?.longitude ?? null,
    // Safely reads the timezone directly from the zone object if it exists
    timezone:  targetTz 
  },
  crop: {
    type:         cropType?.state     ?? null,
    growth_stage: growthStage?.state  ?? null,
    mode:         priorityMode?.state ?? null
  },
  sensors: [
    { type: 'soil_moisture', value: safeParse(soilMoisture?.state), description: null },
    { type: 'temperature',   value: safeParse(temperature?.state),  description: null },
    { type: 'air_humidity',  value: safeParse(airHumidity?.state),  description: null },
    { type: 'luminosity',    value: safeParse(luminosity?.state),   description: null }
  ],
  actuators: [pumpActuator, fanActuator],
  notifications: null,
  warnings,
  recommendation: null,
  weather: { precipitation_probability: null, state: null, summary: null },
  history: { runs: null},
  image_processing: {
    summary: null,
    features: {
      rain_detected: null, water_on_leaves: null, cloud_cover: null,
      lighting_level: null, shadows_present: null, plant_motion_detected: null, motion_intensity: null
    },
    confidence_rain: null,
    confidence_wind:null
  },
};

return [{ json: output }];

// Loop over input items and add a new field called 'myNewField' to the JSON of each one
const piAdr = "host.docker.internal"

return {
  piAdr: piAdr
};
